// Stand-in for a CRM / ERP node: in real workflows this would be a Shopify, HubSpot or Postgres node.
const orders = { A100: 'shipped on 2026-10-20, arriving 2026-10-27', A101: 'processing', A102: 'delivered on 2026-10-18' };
const id = String(query).trim().toUpperCase();
return orders[id] ?? `No order with id ${id}`;

const target = new Date(String(query).trim() + 'T00:00:00Z');
if (isNaN(target)) return `Not a YYYY-MM-DD date: ${query}`;
const today = new Date(new Date().toISOString().slice(0, 10) + 'T00:00:00Z');
return String(Math.round((target - today) / 86400000));
